'use strict';
// Edice 05.5: reusable cafe designs, model-specific equipment and a founder-chosen first address.
const STUDIO_BASE5={fresh,makeStore,openStore,unlocked,nextWeek,validateSave,buyEquipment,serviceEquipment,applyFloor5,equipmentEffects};
STATIONS5.table.seats=4;
STATIONS5.table2={name:'Malý stolek · 2 místa',w:1,h:1,required:false,seats:2};
STATIONS5.barseat={name:'Barové místo · 1 místo',w:1,h:1,required:false,seats:1};
const CAFE_STYLES12={nordic:{name:'Severská · světlé dřevo',wall:'#eeede7',wood:'#bca989',accent:'#555fc0',cost:0},industrial:{name:'Industriální · cihla a ocel',wall:'#c1a092',wood:'#866b51',accent:'#3b4a58',cost:15000},garden:{name:'Zahradní · šalvěj a zeleň',wall:'#d4dfd0',wood:'#a49c78',accent:'#668266',cost:18000},classic:{name:'Klasická · krém a ořech',wall:'#eee2ce',wood:'#87684d',accent:'#766055',cost:22000},coastal:{name:'Přímořská · modrá a bílá',wall:'#edf2f0',wood:'#c5b798',accent:'#6a99b4',cost:18000},night:{name:'Večerní · tmavý bar',wall:'#656b78',wood:'#9e775b',accent:'#6e5b97',cost:25000}};
function cafeAppearance12(s){return s?.appearance||{style:'nordic',terrace:false};}
const FURNITURE5={table:{name:'Stůl a čtyři židle',cost:9000},table2:{name:'Malý stolek a dvě židle',cost:5500},barseat:{name:'Barový pult a stolička',cost:2800}};
const EQUIPMENT_MODELS5={
 machine:{compact:{name:'Compact · 1 páka',cost:45000,maintenance:0,capacity:1,quality:0},standard:{...EQUIPMENT.machine,name:'Barista · 2 páky'},premium:{name:'Signature · 3 páky',cost:175000,maintenance:1650,capacity:1.25,quality:5}},
 grinder:{compact:{name:'Entry · espresso',cost:18000,maintenance:0,capacity:1,quality:0},standard:{...EQUIPMENT.grinder,name:'Precision · espresso'},premium:{name:'Competition · nízká retence',cost:68000,maintenance:650,capacity:1.05,quality:7}},
 filter:{standard:{...EQUIPMENT.filter,name:'Ruční filtrační stanice'},batch:{name:'Batch brew · dávkový filtr',cost:52000,maintenance:500,capacity:1.10,quality:1}},
 bar:{standard:{...EQUIPMENT.bar,name:'Ergonomický bar'},premium:{name:'Bar pro dvě pracovní linky',cost:125000,maintenance:800,capacity:1.28,quality:1}},
 coldbrew:{standard:{...EQUIPMENT.coldbrew,name:'Cold brew · malá výroba'},premium:{name:'Cold brew · čepovaný systém',cost:79000,maintenance:700,capacity:1.06,quality:1}},
 oven:{standard:{...EQUIPMENT.oven,name:'Pec a malá vitrína'},premium:{name:'Konvekční pec a velká vitrína',cost:88000,maintenance:800,capacity:1.03,quality:1}},
 kitchen:{standard:{...EQUIPMENT.kitchen}},window:{standard:{...EQUIPMENT.window}}
};
function cloneStudio5(x){return JSON.parse(JSON.stringify(x))}
function equipmentSpec5(key,item){return EQUIPMENT_MODELS5[key]?.[item?.model||'standard']||EQUIPMENT[key]}
function studioBaseDesign5(){return {appearance:{style:'nordic',terrace:false},floor:defaultFloor5(),layout:'balanced',equipment:{machine:'compact',grinder:'compact',filter:'standard'}}}
function studioStarterDesign6(){const d=studioBaseDesign5();d.floor.items=d.floor.items.filter(i=>!['table-4','table-5'].includes(i.id));return d;}
function cafePreset12(id){if(typeof id!=='string'||!id.startsWith('look-'))return null;const key=id.slice(5).replace(/-terrace$/,''),terrace=id.endsWith('-terrace');if(!CAFE_STYLES12[key])return null;const d=studioStarterDesign6();d.appearance={style:key,terrace};return d;}
function storeDesign5(s){return {appearance:cloneStudio5(cafeAppearance12(s)),floor:cloneStudio5(s.floor),layout:s.layout,equipment:Object.fromEntries(Object.entries(s.equipment).filter(([k])=>k!=='seats').map(([k,e])=>[k,e.model||'standard']))}}
function designInfo5(design){
 if(!design||!['balanced','speed','lounge'].includes(design.layout)||!design.equipment||Array.isArray(design.equipment))throw Error('Zkontroluj vybavení a způsob obsluhy.');
 for(const [key,model] of Object.entries(design.equipment))if(!Object.hasOwn(EQUIPMENT_MODELS5,key)||!Object.hasOwn(EQUIPMENT_MODELS5[key],model))throw Error('Neznámý model vybavení.');
 if(!design.equipment.machine||!design.equipment.grinder)throw Error('Kavárna potřebuje kávovar a mlýnek.');
 if(design.floor?.items?.some(i=>i.kind==='window')&&!design.equipment.window)throw Error('Okénko v půdorysu potřebuje výdejní technologii.');
 if(design.appearance&&(!Object.hasOwn(CAFE_STYLES12,design.appearance.style)||typeof design.appearance.terrace!=='boolean'))throw Error('Vyber platný styl a terasu.');
 const info=floorInfo5(design.floor,100),equipment=Object.fromEntries(Object.entries(design.equipment).map(([k,model])=>[k,{model,condition:100}])),effects=equipmentEffects({equipment});
 return {...info,effects,furniture:design.floor.items.reduce((a,i)=>a+(FURNITURE5[i.kind]?.cost||0),0),equipmentValue:Object.entries(design.equipment).reduce((a,[k,m])=>a+EQUIPMENT_MODELS5[k][m].cost,0)};
}
function ensureStudio5(v){if(v.studio5===undefined)v.studio5={opening:false,designs:[]};for(const s of v.stores){s.equipment.machine??={model:'compact',condition:s.serviceCondition};s.equipment.grinder??={model:'compact',condition:s.serviceCondition};}return v}
fresh=function(scenario='sandbox',difficulty='normal'){const v=ensureStudio5(STUDIO_BASE5.fresh(scenario,difficulty));if(scenario==='sandbox'){v.cash=650000;v.stores=[];v.studio5.opening=true;v.roasters[0].name='Praha · zakladatelská pražírna';v.warehouses[0].name='Praha · první sklad';v.logs=[{week:1,text:'První adresu vybíráš ty.',detail:'Kapitál 650 000 Kč, vlastní pražírna a zásoby kávy. Vyber volnou lokalitu a návrh kavárny.'}];}return v};
SCENARIOS.sandbox.cash=650000;
SCENARIOS.sandbox.description='650 000 Kč, pražírna a zásoby. První kavárnu si vyber a zařiď sám; potom vybuduj mezinárodní síť.';
makeStore=function(...args){const s=STUDIO_BASE5.makeStore(...args);ensureStudio5({stores:[s]});return s};
state=fresh();
unlocked=function(name){return name==='Praha'&&state.studio5?.opening||STUDIO_BASE5.unlocked(name)};
nextWeek=function(...args){if(!state.stores.length&&!(typeof hasOpeningWork6==='function'&&hasOpeningWork6()))throw Error('Nejdřív vyber adresu a otevři svou první kavárnu.');return STUDIO_BASE5.nextWeek(...args)};
equipmentEffects=function(s){let capacity=1,quality=0,cost=0;for(const [key,e] of Object.entries(s.equipment)){const cfg=equipmentSpec5(key,e);capacity*=1+(cfg.capacity-1)*e.condition/100;quality+=cfg.quality*e.condition/100;cost+=cfg.maintenance;}return {capacity:clamp(capacity,.5,1.65),quality,cost}};
function equipmentQuote5(id,key,model){const s=state.stores.find(s=>s.id===id),cfg=EQUIPMENT_MODELS5[key]?.[model];if(!s||s.franchise||!Object.hasOwn(EQUIPMENT_MODELS5,key)||!Object.hasOwn(EQUIPMENT_MODELS5[key],model))throw Error('Vyber vlastní kavárnu a platný model.');const old=s.equipment[key],same=old&&(old.model||'standard')===model,credit=same?0:old?round(equipmentSpec5(key,old).cost*.35*old.condition/100):0;return {store:id,key,model,cost:same?0:cfg.cost-credit,price:same?0:cfg.cost,credit,same:!!same,old:old?cloneStudio5(old):null,weekly:cfg.maintenance};}
function buyEquipmentModel5(id,key,model,expected){guard();const q=equipmentQuote5(id,key,model);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Nabídka se změnila. Otevři ji znovu.');if(q.same)return;spend(q.cost);state.stores.find(s=>s.id===id).equipment[key]={model,condition:100};log('Nové vybavení: '+loc(id).name,EQUIPMENT_MODELS5[key][model].name+' · '+money(q.cost)+', výkup '+money(q.credit)+'.');}
buyEquipment=function(id,key){if(key==='seats')throw Error('Místa nyní přidávej konkrétními stoly ve Studiu kaváren.');return buyEquipmentModel5(id,key,'standard')};
serviceEquipment=function(id,key){guard();const s=state.stores.find(s=>s.id===id),item=s?.equipment[key];if(!item||s.franchise)throw Error('Vybavení není v tvé kavárně instalované.');const cost=round(equipmentSpec5(key,item).cost*.08);spend(cost);item.condition=100;s.serviceCondition=100;state.pendingExpense3=(state.pendingExpense3||0)+cost;log('Servis zařízení: '+loc(id).name,equipmentSpec5(key,item).name+' · '+money(cost));};
function studioChanges5(current,desired,opening=false){
 desired={...desired,appearance:cloneStudio5(cafeAppearance12(desired))};
 const info=designInfo5(desired),base=opening?studioBaseDesign5():storeDesign5(current),lines=[];let purchases=0,credit=0;
 for(const key of new Set([...Object.keys(base.equipment),...Object.keys(desired.equipment)])){const before=base.equipment[key],after=desired.equipment[key];if(before===after)continue;const price=after?EQUIPMENT_MODELS5[key][after].cost:0,trade=before?(opening?EQUIPMENT_MODELS5[key][before].cost:round(EQUIPMENT_MODELS5[key][before].cost*.35*(current.equipment[key]?.condition||0)/100)):0;purchases+=price;credit+=trade;lines.push({label:after?EQUIPMENT_MODELS5[key][after].name:'Odebrání: '+EQUIPMENT_MODELS5[key][before].name,price,credit:trade});}
 for(const [kind,cfg] of Object.entries(FURNITURE5)){const before=base.floor.items.filter(i=>i.kind===kind).length,after=desired.floor.items.filter(i=>i.kind===kind).length,diff=after-before;if(!diff)continue;const price=Math.max(0,diff)*cfg.cost,trade=Math.max(0,-diff)*cfg.cost*(opening?1:.35);purchases+=price;credit+=round(trade);lines.push({label:cfg.name+' · '+(diff>0?'+':'')+diff,price,credit:round(trade)});}
 const beforeAppearance=cafeAppearance12(base),afterAppearance=cafeAppearance12(desired);if(beforeAppearance.style!==afterAppearance.style){const price=CAFE_STYLES12[afterAppearance.style].cost;const trade=round(CAFE_STYLES12[beforeAppearance.style].cost*(opening?1:.35));purchases+=price;credit+=trade;lines.push({label:CAFE_STYLES12[afterAppearance.style].name,price,credit:trade});}if(beforeAppearance.terrace!==afterAppearance.terrace){const price=afterAppearance.terrace?45000:0,trade=beforeAppearance.terrace?(opening?45000:15750):0;purchases+=price;credit+=trade;lines.push({label:afterAppearance.terrace?'Zahrádka · terasa a mobiliář':'Odebrání terasy',price,credit:trade});}
 const changed=JSON.stringify(base)!==JSON.stringify(desired),renovation=!opening&&changed?25000:0;
 return {cost:purchases-credit+renovation,purchases,credit,renovation,lines,changed,info};
}
function designQuote5(id,desired){const s=state.stores.find(s=>s.id===id);if(!s||s.franchise)throw Error('Vyber vlastní kavárnu.');const x=studioChanges5(s,desired);return {store:id,before:storeDesign5(s),conditions:Object.fromEntries(Object.entries(s.equipment).map(([k,e])=>[k,e.condition])),desired:cloneStudio5(desired),...x};}
function installDesign5(s,desired){const old=s.equipment;s.appearance=cloneStudio5(cafeAppearance12(desired));s.floor=cloneStudio5(desired.floor);s.layout=desired.layout;s.seats=designInfo5(desired).seats;s.equipment=Object.fromEntries(Object.entries(desired.equipment).map(([k,model])=>[k,{model,condition:old[k]&&(old[k].model||'standard')===model?old[k].condition:100}]));for(const [key,cfg] of Object.entries(MENU))if(cfg.requires&&!s.equipment[cfg.requires])s.menu[key].enabled=false;}
function applyDesign5(id,desired,expected){guard();const q=designQuote5(id,desired);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Kavárna se změnila. Přepočítej přestavbu.');if(!q.changed)return;if(q.cost>=0)spend(q.cost);else state.cash-=q.cost;installDesign5(state.stores.find(s=>s.id===id),desired);log('Přestavba: '+loc(id).name,'Celkem '+money(q.cost)+' · '+q.info.seats+' míst. Vybavení a půdorys platí pro další provoz.');}
applyFloor5=function(id,floor){const s=state.stores.find(s=>s.id===id);if(!s)throw Error('Neznámá kavárna.');return applyDesign5(id,{...storeDesign5(s),floor})};
function saveDesign5(name,desired,id=null){guard();name=String(name).trim();if(!name||name.length>40)throw Error('Název návrhu musí mít 1–40 znaků.');designInfo5(desired);const list=state.studio5.designs,existing=id&&list.find(d=>d.id===id);if(id&&!existing)throw Error('Návrh už neexistuje.');if(!existing&&list.length>=20)throw Error('Můžeš uložit nejvýše 20 návrhů.');if(list.some(d=>d.name.toLocaleLowerCase()===name.toLocaleLowerCase()&&d!==existing))throw Error('Tento název už má jiný návrh.');const d={id:existing?.id||uid('design'),name,design:cloneStudio5(desired)};if(existing)Object.assign(existing,d);else list.push(d);return d;}
function deleteDesign5(id){guard();if(!state.studio5.designs.some(d=>d.id===id))throw Error('Návrh už neexistuje.');state.studio5.designs=state.studio5.designs.filter(d=>d.id!==id)}
function openingQuote5(id,designId='base',brandId=state.brands[0].id,blendId=state.blends[0].id){const l=loc(id),d=designId==='base'?studioBaseDesign5():designId==='starter'?studioStarterDesign6():cafePreset12(designId)||state.studio5.designs.find(d=>d.id===designId)?.design;if(!l||!d||!brand(brandId)||!blend(blendId))throw Error('Vyber adresu, platný návrh, značku a kávu.');const changes=studioChanges5(null,d,true);return {location:id,designId,brand:brandId,blend:blendId,design:cloneStudio5(d),base:l.setup,cost:l.setup+changes.cost,changes,after:state.cash-l.setup-changes.cost,weekly:Math.ceil(l.traffic/400)*6500+l.rent+4700+changes.info.effects.cost};}
let studioOpeningQuote5=null;
function openingSetupCost5(l){return studioOpeningQuote5?.location===l.id?studioOpeningQuote5.cost:l.setup}
openStore=function(id,brandId=state.brands[0].id,blendId=state.blends[0].id,franchise=false,designId='base',expected){guard();const q=!franchise&&openingQuote5(id,designId,brandId,blendId);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Cena nebo návrh se změnily. Otevři nabídku znovu.');if(q&&state.cash<q.cost)throw Error('Na otevření s tímto vybavením nemáš dost hotovosti.');if(q&&state.stores.length>=4&&state.founderShare<50&&state.expansionBudget<q.cost)throw Error('Mandát boardu musí pokrýt adresu i vybavení.');const priorQuote=studioOpeningQuote5;try{studioOpeningQuote5=q;STUDIO_BASE5.openStore(id,brandId,blendId,franchise);}finally{studioOpeningQuote5=priorQuote;}if(q){installDesign5(state.stores.at(-1),q.design);log('Použit návrh '+(designId==='base'?'Základní kavárna':state.studio5.designs.find(d=>d.id===designId).name),'Celková investice '+money(q.cost)+' · '+q.changes.info.seats+' míst.');}state.studio5.opening=false;};
validateSave=function(v){const oldVersion=v?.version,result=STUDIO_BASE5.validateSave(v);ensureStudio5(result);if(oldVersion<5)result.studio5.opening=false;const fail=()=>{throw Error('Soubor obsahuje neplatný návrh kavárny nebo model zařízení.');},cfg=result.studio5;if(!cfg||typeof cfg.opening!=='boolean'||!Array.isArray(cfg.designs)||cfg.designs.length>20||new Set(cfg.designs.map(d=>d.id)).size!==cfg.designs.length)fail();if(!result.stores.length&&(!cfg.opening||result.scenario!=='sandbox'||(result.week!==1||result.history.length)&&!(typeof allowEmptyOpening6==='function'&&allowEmptyOpening6(result))))fail();if(result.stores.length&&cfg.opening)fail();for(const d of cfg.designs){if(!d||typeof d.id!=='string'||!(/^[a-z0-9-]{1,60}$/).test(d.id)||typeof d.name!=='string'||!d.name.trim()||d.name.length>40)fail();try{designInfo5(d.design)}catch{fail()}}for(const s of result.stores)for(const [key,item] of Object.entries(s.equipment))if(item.model!==undefined&&(!Object.hasOwn(EQUIPMENT_MODELS5,key)||!Object.hasOwn(EQUIPMENT_MODELS5[key],item.model)))fail();return result;};
